+<body>
+<header>
+  <div class="brand">
+    <h1>Grok 4.7 <span id="phase">Ready</span></h1>
+  </div>
+  <div class="actions">
+    <button id="test" type="button">Test</button>
+    <button id="reset" type="button">Reset</button>
+  </div>
+  <div class="telemetry">
+    <div class="stat"><b id="telSpeed">0.0</b><span>Car speed m/s</span></div>
+    <div class="stat"><b id="telTime">0.00</b><span>Time s</span></div>
+    <div class="stat"><b id="telMove">0</b><span>Moving bricks</span></div>
+    <div class="stat"><b id="telImpact">—</b><span>Impact m/s</span></div>
+  </div>
+</header>
+<div id="stage">
+  <canvas id="view" aria-label="Side-view crash test of a car hitting a brick wall"></canvas>
+  <aside>
+    <h2>Settings</h2>
+    <div class="field">
+      <div class="row"><label for="speed">Car speed</label><span class="unit" id="speedOut">22 m/s</span></div>
+      <input id="speed" type="range" min="5" max="45" step="0.5" value="22">
+      <div class="numline"><i>5</i><input id="speedNum" type="number" min="5" max="45" step="0.5" value="22"><i>45</i></div>
+    </div>
+    <div class="field">
+      <div class="row"><label for="columns">Wall columns</label><span class="unit" id="columnsOut">12</span></div>
+      <input id="columns" type="range" min="4" max="24" step="1" value="12">
+      <div class="numline"><i>4</i><input id="columnsNum" type="number" min="4" max="24" step="1" value="12"><i>24</i></div>
+    </div>
+    <div class="field">
+      <div class="row"><label for="rows">Wall rows</label><span class="unit" id="rowsOut">8</span></div>
+      <input id="rows" type="range" min="3" max="16" step="1" value="8">
+      <div class="numline"><i>3</i><input id="rowsNum" type="number" min="3" max="16" step="1" value="8"><i>16</i></div>
+    </div>
+    <div class="field">
+      <div class="row"><label for="layers">Wall depth layers</label><span class="unit" id="layersOut">2</span></div>
+      <input id="layers" type="range" min="1" max="5" step="1" value="2">
+      <div class="numline"><i>1</i><input id="layersNum" type="number" min="1" max="5" step="1" value="2"><i>5</i></div>
+    </div>
+    <div class="field">
+      <div class="row"><label for="mass">Brick mass</label><span class="unit" id="massOut">2.5 kg</span></div>
+      <input id="mass" type="range" min="0.5" max="12" step="0.1" value="2.5">
+      <div class="numline"><i>0.5</i><input id="massNum" type="number" min="0.5" max="12" step="0.1" value="2.5"><i>12</i></div>
+    </div>
+    <p id="summary"></p>
+    <p id="dirty"></p>
+    <h2>Constants</h2>
+    <dl class="consts">
+      <div><dt>Gravity</dt><dd>9.81 m/s²</dd></div>
+      <div><dt>Brick friction</dt><dd>0.72</dd></div>
+      <div><dt>Brick restitution</dt><dd>0.18</dd></div>
+      <div><dt>Ground friction</dt><dd>0.85</dd></div>
+      <div><dt>Car mass</dt><dd>1250 kg</dd></div>
+      <div><dt>Car size</dt><dd>4.20 × 1.45 m</dd></div>
+      <div><dt>Car track</dt><dd>1.80 m</dd></div>
+      <div><dt>Brick face</dt><dd>0.50 × 0.24 m</dd></div>
+      <div><dt>Brick depth</dt><dd>0.25 m</dd></div>
+      <div><dt>Scale</dt><dd>80 px/m</dd></div>
+    </dl>
+    <p class="hint">Space runs the test. R resets. The same settings repeat the same crash.</p>
+  </aside>
+</div>
+<script>
+'use strict';
+
+const GRAVITY = 9.81;
+const BRICK_L = 0.50;
+const BRICK_H = 0.24;
+const BRICK_D = 0.25;
+const BRICK_MU = 0.72;
+const BRICK_E = 0.18;
+const GROUND_MU = 0.85;
+const CAR_MASS = 1250;
+const CAR_LEN = 4.2;
+const CAR_H = 1.45;
+const SCALE = 80;
+const RUNWAY = 7.5;
+const DT = 1 / 480;
+const V_ITERS = 18;
+const P_ITERS = 3;
+const SLOP = 0.0015;
+const REST_V = 0.55;
+const CELL = 0.8;
+const SPEC = 0.045;
+const CAM_YAW = 0.78;
+const CAM_PITCH = 0.34;
+const WHEEL_R = 0.34;
+const CAR_NOSE = 2.20;
+const CAR_REAR = -2.00;
+const WALL_FRONT = 16.2;
+
+const DEFAULTS = Object.freeze({
+  speed: 22,
+  columns: 12,
+  rows: 8,
+  layers: 2,
+  mass: 2.5,
+});
+
+const GROUND = {
+  id: 0,
+  invM: 0,
+  invI: 0,
+  x: 0, y: 0, z: 0, a: 0,
+  vx: 0, vy: 0, vz: 0, w: 0,
+};
+
+function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
+function hypot3(x, y, z) { return Math.hypot(x, y, z); }
+
+function makeBasis(yaw, pitch) {
+  const cp = Math.cos(pitch), sp = Math.sin(pitch);
+  const sy = Math.sin(yaw), cy = Math.cos(yaw);
+  const fx = sy * cp;
+  const fy = -sp;
+  const fz = -cy * cp;
+  let rx = -fz, ry = 0, rz = fx;
+  const rl = Math.hypot(rx, ry, rz) || 1;
+  rx /= rl; ry /= rl; rz /= rl;
+  let ux = ry * fz - rz * fy;
+  let uy = rz * fx - rx * fz;
+  let uz = rx * fy - ry * fx;
+  const ul = Math.hypot(ux, uy, uz) || 1;
+  return { fx, fy, fz, rx, ry, rz, ux: ux / ul, uy: uy / ul, uz: uz / ul };
+}
+
+const BASIS = makeBasis(CAM_YAW, CAM_PITCH);
+const LIGHT = (() => {
+  const x = -0.32, y = 0.90, z = 0.28;
+  const l = Math.hypot(x, y, z);
+  return { x: x / l, y: y / l, z: z / l };
+})();
+
+function shade(rgb, nx, ny, nz, vary) {
+  const nd = Math.max(0, nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z);
+  const f = (0.34 + 0.72 * nd) * vary;
+  const r = clamp((rgb[0] * f) | 0, 0, 255);
+  const g = clamp((rgb[1] * f) | 0, 0, 255);
+  const b = clamp((rgb[2] * f) | 0, 0, 255);
+  return `rgb(${r},${g},${b})`;
+}
+
+function hexRgb(hex) {
+  const n = parseInt(hex.slice(1), 16);
+  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
+}
+
+const BRICK_PALETTE = ['#a34536', '#8e3a30', '#b55242', '#974238', '#c25a45', '#7d342c', '#b04838'].map(hexRgb);
+
+function syncRot(b) {
+  b.c = Math.cos(b.a);
+  b.s = Math.sin(b.a);
+}
+
+function makeBrick(spec) {
+  const m = spec.mass;
+  const I = m * (spec.hx * spec.hx + spec.hy * spec.hy) / 3;
+  const b = {
+    id: spec.id,
+    type: 'brick',
+    x: spec.x, y: spec.y, z: spec.z, a: 0,
+    vx: 0, vy: 0, vz: 0, w: 0,
+    hx: spec.hx, hy: spec.hy, hz: spec.hz,
+    m, invM: 1 / m, invI: 1 / Math.max(I, 1e-6),
+    awake: false,
+    sleepT: 0,
+    mu: BRICK_MU,
+    e: BRICK_E,
+    half: spec.half,
+    row: spec.row,
+    layer: spec.layer,
+    neighbors: [],
+    supporters: [],
+    rgb: BRICK_PALETTE[(spec.id * 3 + spec.row * 5 + spec.layer) % BRICK_PALETTE.length],
+    vary: 0.90 + ((spec.id * 17) % 11) * 0.012,
+    _stamp: 0,
+  };
+  syncRot(b);
+  return b;
+}
+
+function carFixtures() {
+  const boxes = [
+    { name: 'body', lx: 0.05, ly: -0.02, lz: 0, hx: 1.55, hy: 0.22, hz: 0.90 },
+    { name: 'nose', lx: 1.86, ly: -0.08, lz: 0, hx: 0.34, hy: 0.20, hz: 0.90 },
+    { name: 'hood', lx: 1.22, ly: 0.16, lz: 0, hx: 0.52, hy: 0.10, hz: 0.86 },
+    { name: 'cab', lx: -0.02, ly: 0.46, lz: 0, hx: 0.78, hy: 0.43, hz: 0.78 },
+    { name: 'wind', lx: 0.92, ly: 0.34, lz: 0, hx: 0.26, hy: 0.26, hz: 0.74 },
+    { name: 'trunk', lx: -1.22, ly: 0.20, lz: 0, hx: 0.70, hy: 0.16, hz: 0.84 },
+    { name: 'rear', lx: -1.88, ly: -0.08, lz: 0, hx: 0.12, hy: 0.16, hz: 0.88 },
+  ];
+  const wheels = [
+    { lx: -1.36, ly: -0.22, lz: 0.78 },
+    { lx: -1.36, ly: -0.22, lz: -0.78 },
+    { lx: 1.40, ly: -0.22, lz: 0.78 },
+    { lx: 1.40, ly: -0.22, lz: -0.78 },
+  ];
+  return { boxes, wheels };
+}
+
+function createCar() {
+  const { boxes, wheels } = carFixtures();
+  const wheelM = 22;
+  let boxVol = 0;
+  for (const f of boxes) boxVol += f.hx * f.hy * f.hz;
+  const boxM = CAR_MASS - wheelM * wheels.length;
+  let I = 0;
+  const fixtures = [];
+  boxes.forEach((f, i) => {
+    const m = boxM * (f.hx * f.hy * f.hz) / boxVol;
+    I += m * (f.hx * f.hx + f.hy * f.hy) / 3 + m * (f.lx * f.lx + f.ly * f.ly);
+    fixtures.push({
+      kind: 'box', index: i, m,
+      lx: f.lx, ly: f.ly, lz: f.lz,
+      hx: f.hx, hy: f.hy, hz: f.hz,
+      mu: BRICK_MU, e: 0.10,
+    });
+  });
+  wheels.forEach((w, i) => {
+    I += 0.5 * wheelM * WHEEL_R * WHEEL_R + wheelM * (w.lx * w.lx + w.ly * w.ly);
+    fixtures.push({
+      kind: 'circle', index: boxes.length + i, m: wheelM,
+      lx: w.lx, ly: w.ly, lz: w.lz,
+      r: WHEEL_R, hz: 0.13,
+      mu: GROUND_MU, e: 0.02,
+      wheel: true,
+    });
+  });
+  const restY = 0.56;
+  const spawnX = WALL_FRONT - CAR_NOSE - RUNWAY;
+  return {
+    id: 1,
+    type: 'car',
+    x: spawnX, y: restY, z: 0, a: 0,
+    vx: 0, vy: 0, vz: 0, w: 0,
+    spawnX, restY,
+    m: CAR_MASS, invM: 1 / CAR_MASS, invI: 1 / I,
+    awake: true,
+    wheelsLocked: false,
+    wheelA: 0,
+    fixtures,
+    mu: BRICK_MU,
+    e: 0.10,
+    crumple: 0,
+  };
+}
+
+function wallStats(cfg) {
+  let pieces = 0;
+  let equiv = 0;
+  for (let d = 0; d < cfg.layers; d++) {
+    for (let r = 0; r < cfg.rows; r++) {
+      const offset = ((r + d) & 1) === 1;
+      if (offset) {
+        pieces += cfg.columns + 1;
+        equiv += cfg.columns;
+      } else {
+        pieces += cfg.columns;
+        equiv += cfg.columns;
+      }
+    }
+  }
+  return { pieces, mass: equiv * cfg.mass, equiv };
+}
+
+function createWorld(cfg) {
+  const settings = {
+    speed: clamp(+cfg.speed, 5, 45),
+    columns: clamp(cfg.columns | 0, 4, 24),
+    rows: clamp(cfg.rows | 0, 3, 16),
+    layers: clamp(cfg.layers | 0, 1, 5),
+    mass: clamp(+cfg.mass, 0.5, 12),
+  };
+  const bricks = [];
+  let id = 2;
+  const z0 = -settings.columns * BRICK_L / 2;
+  const W = settings.columns * BRICK_L;
+  for (let d = 0; d < settings.layers; d++) {
+    const x = WALL_FRONT + BRICK_D * (d + 0.5);
+    for (let r = 0; r < settings.rows; r++) {
+      const y = BRICK_H * (r + 0.5);
+      const offset = ((r + d) & 1) === 1;
+      if (!offset) {
+        for (let c = 0; c < settings.columns; c++) {
+          bricks.push(makeBrick({
+            id: id++, x, y, z: z0 + (c + 0.5) * BRICK_L,
+            hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 2,
+            mass: settings.mass, half: false, row: r, layer: d,
+          }));
+        }
+      } else {
+        bricks.push(makeBrick({
+          id: id++, x, y, z: z0 + BRICK_L / 4,
+          hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 4,
+          mass: settings.mass * 0.5, half: true, row: r, layer: d,
+        }));
+        for (let i = 0; i < settings.columns - 1; i++) {
+          bricks.push(makeBrick({
+            id: id++, x, y, z: z0 + (i + 1) * BRICK_L,
+            hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 2,
+            mass: settings.mass, half: false, row: r, layer: d,
+          }));
+        }
+        bricks.push(makeBrick({
+          id: id++, x, y, z: z0 + W - BRICK_L / 4,
+          hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 4,
+          mass: settings.mass * 0.5, half: true, row: r, layer: d,
+        }));
+      }
+    }
+  }
+  linkNeighbors(bricks);
+  const car = createCar();
+  syncRot(car);
+  const world = {
+    cfg: settings,
+    bricks,
+    car,
+    phase: 'idle',
+    simTime: 0,
+    frame: 0,
+    stamp: 1,
+    impactSpeed: null,
+    stillT: 0,
+    moving: 0,
+    shake: 0,
+    flash: 0,
+    particles: [],
+    skidL: [],
+    skidR: [],
+    contacts: [],
+    warm: new Map(),
+    didImpactWake: false,
+    lastSmoke: -1,
+    stats: { contacts: 0, awake: 0, maxPen: 0 },
+    basis: BASIS,
+    focus: { x: 10, y: 1, z: 0 },
+    viewScale: SCALE,
+    wallFront: WALL_FRONT,
+    wallBack: WALL_FRONT + settings.layers * BRICK_D,
+    wallW: W,
+    wallH: settings.rows * BRICK_H,
+  };
+  return world;
+}
+
+function sepAxis(a0, a1, b0, b1) {
+  return Math.min(a1, b1) - Math.max(a0, b0);
+}
+
+function linkNeighbors(bricks) {
