const B = box(0.2,0.12,0, 0.125,0.12,0.25); // overlap in x: centers 0.2 apart, half 0.125*2=0.25, overlap=0.05
let sat = lab.satBoxBox(A,B,0.02);
console.log("x overlap", sat && {pen:+sat.pen.toFixed(4), n:[+sat.nx.toFixed(3),+sat.ny.toFixed(3),+sat.nz.toFixed(3)]});
const C = box(0,0.24,0, 0.125,0.12,0.25);
sat = lab.satBoxBox(A,C,0.02);
console.log("y stack touch", sat && {pen:+sat.pen.toFixed(5), n:[+sat.nx.toFixed(3),+sat.ny.toFixed(3),+sat.nz.toFixed(3)], ref:sat.ref});
const man = sat && lab.manifoldBoxBox(A,C,sat);
console.log("manifold points", man && man.length, man && man.map(p=>({pen:+p.pen.toFixed(5), px:+p.px.toFixed(3), py:+p.py.toFixed(3)})));

const D = box(0,0.5,0, 0.125,0.12,0.25);
sat = lab.satBoxBox(A,D,0.02);
console.log("separated y", sat);

// stack of 10 all awake
const w = lab.createWorld(lab.DEFAULTS);
console.log("bricks", w.bricks.length, "mass", lab.wallStats(w.cfg));
for (const b of w.bricks) b.awake = true;
const y0 = w.bricks.map(b=>b.y);
const tStack = Date.now();
lab.integrate(w, 2.0);
const dtStack = Date.now()-tStack;
let maxDrift = 0, maxY = 0, nan=0;
for (let i=0;i<w.bricks.length;i++){
  const b=w.bricks[i];
  if (!Number.isFinite(b.x)||!Number.isFinite(b.y)||!Number.isFinite(b.a)) nan++;
  maxDrift = Math.max(maxDrift, Math.hypot(b.x- (b.x), 0)); // placeholder
  const dx = Math.abs(b.x - (WALL?0:b.x));
}
// compare to initial by rebuilding
const w2 = lab.createWorld(lab.DEFAULTS);
let maxDX=0,maxDY=0,maxDZ=0,maxDA=0;
for (let i=0;i<w.bricks.length;i++){
