  maxDX=Math.max(maxDX, Math.abs(a.x-b.x));
  maxDY=Math.max(maxDY, Math.abs(a.y-b.y));
  maxDZ=Math.max(maxDZ, Math.abs(a.z-b.z));
  maxDA=Math.max(maxDA, Math.abs(a.a-b.a));
}
console.log({dtStack, nan, maxDX, maxDY, maxDZ, maxDA, contacts:w.stats.contacts, awake:w.stats.awake, maxPen:w.stats.maxPen});
END

