args.command:
node << 'END'
const fs = require("fs");
const vm = require("vm");
const html = fs.readFileSync("index.html","utf8");
vm.runInThisContext(html.slice(html.indexOf("<script>")+8, html.lastIndexOf("</script>")));
const lab = globalThis.__crashlab;

function driftTest(label, cfg, seconds) {
  const w = lab.createWorld(cfg);
  w.phase = 'dynamic';
  w.didImpactWake = true;
  w.car.vx = 0;
  w.car.wheelsLocked = true;
  for (const b of w.bricks) b.awake = true;
  const init = w.bricks.map(b => ({x:b.x,y:b.y,z:b.z,a:b.a}));
  const t0 = Date.now();
  lab.integrate(w, seconds);
  let maxDX=0,maxDY=0,maxDZ=0,maxDA=0, nan=0, minY=Infinity;
  for (let i=0;i<w.bricks.length;i++){
    const b=w.bricks[i], a=init[i];
    if (!Number.isFinite(b.x+b.y+b.z+b.a+b.vx)) nan++;
    maxDX=Math.max(maxDX, Math.abs(b.x-a.x));
    maxDY=Math.max(maxDY, Math.abs(b.y-a.y));
    maxDZ=Math.max(maxDZ, Math.abs(b.z-a.z));
    maxDA=Math.max(maxDA, Math.abs(b.a-a.a));
    minY=Math.min(minY, b.y-b.hy);
  }
  console.log(label, {ms:Date.now()-t0, bricks:w.bricks.length, nan, maxDX:+maxDX.toFixed(4), maxDY:+maxDY.toFixed(4), maxDZ:+maxDZ.toFixed(4), maxDA:+maxDA.toFixed(4), minY:+minY.toFixed(4), contacts:w.stats.contacts, awake:w.stats.awake, maxPen:+w.stats.maxPen.toFixed(4), carY:+w.car.y.toFixed(3), carA:+w.car.a.toFixed(3)});
}

driftTest("stack8", {speed:22, columns:4, rows:8, layers:1, mass:2.5}, 2);
driftTest("wall default awake", lab.DEFAULTS, 1.5);

function runCrash(label, cfg, seconds) {
  const w = lab.createWorld(cfg);
  w.phase = 'launch';
  const init = w.bricks.map(b => ({x:b.x,y:b.y,z:b.z}));
  const t0 = Date.now();
  lab.integrate(w, seconds);
  let moved=0, maxDisp=0, nan=0, fly=0;
  for (let i=0;i<w.bricks.length;i++){
    const b=w.bricks[i], a=init[i];
    if (!Number.isFinite(b.x+b.y+b.vx+b.a)) nan++;
    const d=Math.hypot(b.x-a.x, b.y-a.y, b.z-a.z);
    if (d>0.05) moved++;
    if (d>maxDisp) maxDisp=d;
    if (b.y>3 || b.x>w.wallBack+8) fly++;
  }
  const cs=Math.hypot(w.car.vx,w.car.vy,w.car.vz);
  console.log(label, {
    ms:Date.now()-t0, phase:w.phase, t:+w.simTime.toFixed(2),
    impact:w.impactSpeed,
    carX:+w.car.x.toFixed(2), carV:+cs.toFixed(2), carA:+w.car.a.toFixed(3),
    wallFront:w.wallFront, wallBack:+w.wallBack.toFixed(2),
    moved, maxDisp:+maxDisp.toFixed(2), fly, nan,
    moving:w.moving, awake:w.stats.awake, contacts:w.stats.contacts, maxPen:+w.stats.maxPen.toFixed(3)
  });
  return w;
}

const a = runCrash("default 3.5s", lab.DEFAULTS, 3.5);
const b = runCrash("default 3.5s again", lab.DEFAULTS, 3.5);
const sa = lab.snapshotPhysics(a);
const sb = lab.snapshotPhysics(b);
let md=0;
for (let i=0;i<sa.length;i++) md=Math.max(md, Math.abs(sa[i]-sb[i]));
console.log("determinism max delta", md);

runCrash("heavy slow", {speed:5, columns:12, rows:8, layers:2, mass:12}, 4.5);
runCrash("light fast", {speed:40, columns:12, rows:8, layers:2, mass:0.5}, 2.2);
