node << 'END'
const fs = require("fs");
const vm = require("vm");
const html = fs.readFileSync("index.html","utf8");
vm.runInThisContext(html.slice(html.indexOf("<script>")+8, html.lastIndexOf("</script>")));
const lab = globalThis.__crashlab;

function watch(label, bricksN, rows) {
  const w = lab.createWorld({speed:22, columns:4, rows, layers:1, mass:2.5});
  w.phase = 'dynamic';
  w.didImpactWake = true;
  // park the car far and freeze it
  w.car.x = -20; w.car.vx=0; w.car.invM=0; w.car.invI=0; w.car.wheelsLocked=true;
  const use = w.bricks.filter(b => b.layer===0).slice(0, bricksN);
  for (const b of w.bricks) b.awake = false;
  for (const b of use) b.awake = true;
  console.log('\n'+label, 'n', use.length, 'ids', use.map(b=>b.id+'@'+b.y.toFixed(2)));
  for (const t of [0.05, 0.2, 0.5, 1.0]) {
    const target = Math.round(t / lab.DT);
    while (w.frame < target) lab.step(w, lab.DT);
    const parts = use.map(b => {
      return `y${b.y.toFixed(3)} x${b.x.toFixed(3)} a${b.a.toFixed(3)} v${b.vx.toFixed(2)},${b.vy.toFixed(2)} w${b.w.toFixed(2)}`;
    });
    console.log('t', t, 'contacts', w.stats.contacts, 'pen', w.stats.maxPen.toFixed(4));
    console.log(parts.join(' | '));
  }
}
watch('one ground brick', 1, 1);
watch('two stack', 2, 2);
END

