  w.phase = 'dynamic';
  w.didImpactWake = true;
  w.car.sleepT = 999;
  w.car.vx=w.car.vy=w.car.w=0;
  // wake one column: same x,z neighborhood from bottom
  const base = w.bricks.find(b => b.row===0 && !b.half && b.layer===0);
  const col = w.bricks.filter(b => Math.abs(b.x-base.x)<0.02 && Math.abs(b.z-base.z)<0.26);
  for (const b of w.bricks) b.awake = false;
  for (const b of col) b.awake = true;
  console.log(label, 'awake', col.length, 'of', w.bricks.length, 'rows', [...new Set(col.map(b=>b.row))].length);
  const init = new Map(col.map(b=>[b.id, {x:b.x,y:b.y,z:b.z}]));
  const t0 = performance.now();
  const steps = Math.round(1.5 / lab.DT);
  for (let i=0;i<steps;i++) lab.step(w, lab.DT);
  let maxD=0, maxA=0;
  for (const b of col) {
    const a = init.get(b.id);
    maxD = Math.max(maxD, Math.hypot(b.x-a.x, b.y-a.y, b.z-a.z));
    maxA = Math.max(maxA, Math.abs(b.a));
  }
