const lab = globalThis.__crashlab;

function column(rows, seconds) {
  const w = lab.createWorld({speed:22, columns:6, rows, layers:2, mass:2.5});
  w.phase = 'dynamic';
  w.didImpactWake = true;
  w.car.sleepT = 999;
  const base = w.bricks.find(b => b.row===0 && !b.half && b.layer===0);
  const col = w.bricks.filter(b => Math.abs(b.x-base.x)<0.02 && Math.abs(b.z-base.z)<0.3);
  for (const b of w.bricks) b.awake = false;
  for (const b of col) b.awake = true;
  const init = new Map(col.map(b=>[b.id,{x:b.x,y:b.y,z:b.z}]));
  const t0=performance.now();
  for (let i=0;i<Math.round(seconds/lab.DT);i++) lab.step(w, lab.DT);
  let maxD=0,maxA=0;
  for (const b of col) {
    const a=init.get(b.id);
    maxD=Math.max(maxD, Math.hypot(b.x-a.x,b.y-a.y,b.z-a.z));
    maxA=Math.max(maxA, Math.abs(b.a));
  }
  console.log('col', rows, 'n', col.length, {ms:+(performance.now()-t0).toFixed(0), maxD:+maxD.toFixed(4), maxA:+maxA.toFixed(4), pen:+w.stats.maxPen.toFixed(4)});
}
