args.streamContent:
function alignedFaceContact(A, B, margin) {
  if (Math.abs(A.a) > 0.22 || Math.abs(B.a) > 0.22) return null;
  const x0 = Math.max(A.x - A.hx, B.x - B.hx);
  const x1 = Math.min(A.x + A.hx, B.x + B.hx);
  const y0 = Math.max(A.y - A.hy, B.y - B.hy);
  const y1 = Math.min(A.y + A.hy, B.y + B.hy);
  const z0 = Math.max(A.z - A.hz, B.z - B.hz);
  const z1 = Math.min(A.z + A.hz, B.z + B.hz);
  const penX = x1 - x0, penY = y1 - y0, penZ = z1 - z0;
  if (penX < -margin || penY < -margin || penZ < -margin) return [];
  let axis = 0;
  let pen = penX;
  if (penY < pen) { pen = penY; axis = 1; }
  if (penZ < pen) { pen = penZ; axis = 2; }
  const tangA = axis === 0 ? penY : penX;
  const tangB = axis === 2 ? penY : penZ;
  // Ignore corner and edge kisses. Faces with real overlap still push.
  if (tangA < 0.02 || tangB < 0.02) return [];
  let nx = 0, ny = 0, nz = 0;
  if (axis === 0) nx = (B.x >= A.x) ? 1 : -1;
  else if (axis === 1) ny = (B.y >= A.y) ? 1 : -1;
  else nz = (B.z >= A.z) ? 1 : -1;
  return [{
    nx, ny, nz, pen,
    px: (x0 + x1) * 0.5,
