function buildHash(world) {
  const map = new Map();
  const inv = 1 / CELL;
  const bricks = world.bricks;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    const ix0 = Math.floor((b.x - b.hx) * inv);
    const ix1 = Math.floor((b.x + b.hx) * inv);
    const iy0 = Math.floor((b.y - b.hy) * inv);
    const iy1 = Math.floor((b.y + b.hy) * inv);
    const iz0 = Math.floor((b.z - b.hz) * inv);
    const iz1 = Math.floor((b.z + b.hz) * inv);
