const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html','utf8');
const start = html.indexOf('<script>') + 8;
const end = html.lastIndexOf('</script>');
const ctx = { console, performance: { now: () => Date.now() }, Math, Map, Set, Float64Array, Object, Number, Array, Infinity };
ctx.globalThis = ctx;
vm.runInNewContext(html.slice(start, end), ctx);
const lab = ctx.__crashlab;

function sample(w, t0pos) {
  const car = w.car;
  let near=0, side=0, sideMoved=0, fly=0, maxD=0, maxSp=0, maxA=0, ke=0, awake=0;
  for (let i=0;i<w.bricks.length;i++) {
    const b = w.bricks[i];
    if (b.awake) awake++;
    const p0 = t0pos[i];
    const d = Math.hypot(b.x-p0.x, b.y-p0.y, b.z-p0.z);
    if (d < 0.08) near++;
    if (d > maxD) maxD = d;
    const sp = Math.hypot(b.vx,b.vy,b.vz);
    if (sp > maxSp) maxSp = sp;
    if (Math.abs(b.a) > maxA) maxA = Math.abs(b.a);
    if (Math.abs(b.z) > 1.35) { side++; if (d > 0.2) sideMoved++; }
    if (d > 2) fly++;
    ke += 0.5*b.m*sp*sp;
  }
  return {
    t:+w.simTime.toFixed(2), vx:+car.vx.toFixed(2), x:+car.x.toFixed(2),
    nose:+(car.x+lab.CAR_NOSE).toFixed(2), a:+car.a.toFixed(3), y:+car.y.toFixed(2),
    near, sideMoved: sideMoved+'/'+side, fly, maxD:+maxD.toFixed(2),
    maxSp:+maxSp.toFixed(2), maxA:+maxA.toFixed(2), awake,
    pen:+w.stats.maxPen.toFixed(3), moving:w.moving, ke:+ke.toFixed(0), phase:w.phase
  };
}
function run(cfg, T, marks) {
  const w = lab.createWorld(cfg);
  const t0 = w.bricks.map(b=>({x:b.x,y:b.y,z:b.z}));
  w.phase='launch';
  const want=new Set(marks.map(t=>Math.round(t/lab.DT)));
  const n=Math.round(T/lab.DT);
  const t1=Date.now();
  const out=[];
  for(let i=0;i<n;i++){ lab.step(w,lab.DT); if(want.has(i+1)) out.push(sample(w,t0)); }
  return {ms:Date.now()-t1, out};
}
console.log('DEFAULT');
const d=run(lab.DEFAULTS, 1.8, [0.70, 0.85, 1.1, 1.8]);
console.log('ms', d.ms);
for (const s of d.out) console.log(JSON.stringify(s));
console.log('SLOW HEAVY');
for (const s of run({speed:8,columns:12,rows:8,layers:2,mass:10}, 1.6, [1.0,1.6]).out) console.log(JSON.stringify(s));
console.log('FAST LIGHT');
for (const s of run({speed:40,columns:12,rows:8,layers:2,mass:0.8}, 1.1, [0.8,1.1]).out) console.log(JSON.stringify(s));
console.log('REST');
{
  const w=lab.createWorld(lab.DEFAULTS);
  const t0=w.bricks.map(b=>({x:b.x,y:b.y,z:b.z}));
  w.phase='dynamic'; w.car.x=-80; w.car.sleepT=999;
  for (const b of w.bricks) b.awake=true;
  const t1=Date.now();
  lab.integrate(w, 0.8);
  let maxD=0,maxA=0;
  for (let i=0;i<w.bricks.length;i++){
    const b=w.bricks[i],p=t0[i];
    maxD=Math.max(maxD, Math.hypot(b.x-p.x,b.y-p.y,b.z-p.z));
    maxA=Math.max(maxA, Math.abs(b.a));
  }
  console.log({maxD, maxA, ms:Date.now()-t1});
}
EOF

