function relOf(A, B) {
  const a = A.body || A;
  const b = B.body || B;
  const vx = (b.vx || 0) - (a.vx || 0);
  const vy = (b.vy || 0) - (a.vy || 0);
  const vz = (b.vz || 0) - (a.vz || 0);
  if (vx * vx + vy * vy + vz * vz < 0.64) return null;
  return { vx, vy, vz };
}

function plowDir(A, B) {
  const a = A.body || A;
  const b = B.body || B;
  const aHeavy = (a.invM || 1) * 4 < (b.invM || 1);
  const bHeavy = (b.invM || 1) * 4 < (a.invM || 1);
  const h = aHeavy ? a : bHeavy ? b : null;
  if (!h) return null;
  return { vx: h.vx || 0, vy: h.vy || 0, vz: h.vz || 0 };
}

function chooseFace(cands, rel, plow) {
  if (plow) {
    const sp2 = plow.vx * plow.vx + plow.vy * plow.vy + plow.vz * plow.vz;
