        if (c.pen <= 0.001) continue;
        const align = Math.abs(plow.vx * c.nx + plow.vy * c.ny + plow.vz * c.nz) / sp;
        if (align < 0.6) continue;
        if (!along || c.pen < along.pen) along = c;
      }
      if (along) return along;
    }
  }
  let best = cands[0];
  for (let i = 1; i < cands.length; i++) if (cands[i].pen < best.pen) best = cands[i];
  if (!rel) return best;
  let closing = null;
  for (let i = 0; i < cands.length; i++) {
    const c = cands[i];
    const vn = rel.vx * c.nx + rel.vy * c.ny + rel.vz * c.nz;
