const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html','utf8');
const ctx = { console, Math, Map, Set, Float64Array, Object, Number, Array, Infinity, performance:{now:()=>Date.now()} };
ctx.globalThis = ctx;
vm.runInNewContext(html.slice(html.indexOf('<script>')+8, html.lastIndexOf('</script>')), ctx);
const lab = ctx.__crashlab;
function sample(w, t0) {
  const car=w.car; let near=0,wing=0,wingM=0,fly=0,maxD=0,maxSp=0,maxA=0,awake=0;
  for (let i=0;i<w.bricks.length;i++){
    const b=w.bricks[i], p=t0[i];
    if (b.awake) awake++;
    const d=Math.hypot(b.x-p.x,b.y-p.y,b.z-p.z);
    if (d<0.15) near++;
    if (d>maxD) maxD=d;
    const sp=Math.hypot(b.vx,b.vy,b.vz);
    if (sp>maxSp) maxSp=sp;
    if (Math.abs(b.a)>maxA) maxA=Math.abs(b.a);
    if (Math.abs(p.z)>2.2){ wing++; if(d>0.35) wingM++; }
    if (d>1.5) fly++;
  }
  return {t:+w.simTime.toFixed(2), vx:+car.vx.toFixed(2), vy:+car.vy.toFixed(2), nose:+(car.x+lab.CAR_NOSE).toFixed(2), a:+car.a.toFixed(3), y:+car.y.toFixed(2), near, wing:wingM+'/'+wing, fly, maxD:+maxD.toFixed(2), maxSp:+maxSp.toFixed(1), maxA:+maxA.toFixed(2), awake, pen:+w.stats.maxPen.toFixed(3), mov:w.moving, phase:w.phase};
}
function run(label, cfg, T, marks) {
  const w=lab.createWorld(cfg);
  const t0=w.bricks.map(b=>({x:b.x,y:b.y,z:b.z}));
  w.phase='launch';
  const want=new Set(marks.map(t=>Math.round(t/lab.DT)));
  const n=Math.round(T/lab.DT);
  const t1=Date.now();
  console.log('\n'+label);
  for (let i=0;i<n;i++){
    lab.step(w, lab.DT);
    if (want.has(i+1)) console.log(JSON.stringify(sample(w,t0)));
  }
  console.log('ms', Date.now()-t1);
  return w;
}
const a=run('DEFAULT', lab.DEFAULTS, 1.6, [0.72, 1.0, 1.6]);
const w2=lab.createWorld(lab.DEFAULTS); w2.phase='launch';
const s1=lab.snapshotPhysics(a);
// second run for determinism only to 1.0 to save time
const b=lab.createWorld(lab.DEFAULTS); b.phase='launch'; lab.integrate(b, 1.0);
const c=lab.createWorld(lab.DEFAULTS); c.phase='launch'; lab.integrate(c, 1.0);
const A=lab.snapshotPhysics(b), B=lab.snapshotPhysics(c);
let delta=0; for (let i=0;i<A.length;i++) delta=Math.max(delta, Math.abs(A[i]-B[i]));
console.log('delta', delta);
run('HEAVY', {speed:8,columns:12,rows:8,layers:2,mass:10}, 3.0, [2.0, 2.5, 3.0]);
run('LIGHT', {speed:40,columns:12,rows:8,layers:2,mass:0.8}, 1.15, [0.5, 0.8, 1.15]);
EOF

